-- ---------------------------------------------------------------------------
-- 2. Aliases
-- ---------------------------------------------------------------------------
--
-- CVs abbreviate. A parser that only matched the canonical form would miss
-- most real mentions: "JS", "MS Excel", "book keeping", "fundi", "boda".
-- Lower-cased on the way in, so lookup is a plain equality test.

CREATE TABLE IF NOT EXISTS public.skill_aliases (
  alias     TEXT PRIMARY KEY,
  canonical TEXT NOT NULL
);

ALTER TABLE public.skill_aliases ENABLE ROW LEVEL SECURITY;

-- Reference data, readable by anyone signed in. There is no write policy:
-- the vocabulary is generated, not user-editable.
DROP POLICY IF EXISTS "Anyone may read skill aliases" ON public.skill_aliases;
CREATE POLICY "Anyone may read skill aliases"
  ON public.skill_aliases FOR SELECT
  USING (true);

ON CONFLICT (alias) DO UPDATE SET canonical = EXCLUDED.canonical;
